public str getName()
{
    return fieldPName(WHSInventFixedLocation, InventLocationId);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::String);
    WHSInventFixedLocation wHSInventFixedLocation;

    while select wHSInventFixedLocation
        group by InventLocationId
    {
        if (! ret.in(wHSInventFixedLocation.InventLocationId))
        {
            ret.add(wHSInventFixedLocation.InventLocationId);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(WHSInventFixedLocation, InventLocationId));
    qbr.value(queryValue(_value));
}
